import type { PaletteMode, ThemeOptions } from '@mui/material/styles';
import deepmerge from '@mui/utils/deepmerge';
import type { SvTokens } from './tokens';

/** Raw options only: MUI must derive helpers after consumer overrides are merged. */
export function svColorDefaults(mode: PaletteMode) {
  const dark = mode === 'dark';
  return {
    palette: {
      mode,
      primary: { main: '#a288e3', contrastText: '#221638' },
      secondary: { main: dark ? '#b9a5eb' : '#7150ad' },
      error: { main: dark ? '#ff8978' : '#b93524' },
      success: { main: dark ? '#13b240' : '#08772a' },
      background: {
        default: dark ? '#141414' : '#f7f7f7',
        paper: dark ? '#1f1f1f' : '#fff',
      },
      text: {
        primary: dark ? '#fff' : '#1c1c1c',
        secondary: dark ? '#a3a3a3' : '#666',
      },
      divider: dark ? '#444' : '#ccc',
    },
    sv: {
      accent: '#a288e3',
      accentHover: '#b5a0e9',
      surface: dark ? '#ffffff0f' : '#1414140f',
      surfaceHover: dark ? '#ffffff1a' : '#1414141a',
      stroke: dark ? '#444' : '#ccc',
      green: '#13b240',
      greenHover: '#1fbf4c',
      focus: dark ? '#c1abf0' : '#7150ad',
    } satisfies SvTokens,
  };
}

export function mergeSvThemeOptions(
  defaults: ThemeOptions,
  options: ThemeOptions
): ThemeOptions {
  const merged = deepmerge(defaults, options);
  if (!options.cssVariables && !options.colorSchemes) return merged;

  const defaultScheme =
    options.defaultColorScheme ?? options.palette?.mode ?? 'light';
  const schemes = { [defaultScheme]: true, ...options.colorSchemes };
  for (const mode of ['light', 'dark'] as const) {
    const scheme = schemes[mode];
    if (!scheme) continue;
    schemes[mode] = deepmerge(svColorDefaults(mode), {
      ...(scheme === true ? {} : scheme),
      ...(options.sv ? { sv: options.sv } : {}),
    });
  }
  merged.colorSchemes = schemes;
  // Only an explicitly supplied palette should override colorSchemes in MUI.
  if (!options.palette) delete merged.palette;
  return merged;
}
